"use client";
import { useState } from "react";
import Sidebar from "@/app/Components/Sidebar";
import ChatWindow from "./Components/ChatWindow";

// Define TypeScript Interfaces
interface Conversation {
  id: string;
  name: string;
  avatar: string;
  lastMessage: string;
}

interface Group {
  id: string;
  name: string;
  avatar: string;
}

interface StatusUpdate {
  id: string;
  user: string;
  status: string;
  time: string;
}

interface Call {
  id: string;
  name: string;
  time: string;
  type: "audio" | "video";
}

interface MessageType {
  id: number;
  userId: string;
  text: string;
  sender: "sender" | "receiver";
  time: string;
}

// Home Component
export default function Home() {
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<{ [key: string]: MessageType[] }>({
    "1": [
      {
        id: 1,
        userId: "user123",
        text: "Hey, John!",
        sender: "sender",
        time: "10:00 AM",
      },
      {
        id: 2,
        userId: "1",
        text: "Hey, how are you?",
        sender: "receiver",
        time: "10:05 AM",
      },
    ],
    "2": [
      {
        id: 1,
        userId: "user123",
        text: "Hi, Jane!",
        sender: "sender",
        time: "11:00 AM",
      },
      {
        id: 2,
        userId: "2",
        text: "Let’s catch up soon!",
        sender: "receiver",
        time: "11:15 AM",
      },
    ],
  });

  const conversations: Conversation[] = [
    {
      id: "1",
      name: "John Doe",
      avatar: "https://i.pravatar.cc/150?img=1",
      lastMessage: "Hey, how are you?",
    },
    {
      id: "2",
      name: "Jane Smith",
      avatar: "https://i.pravatar.cc/150?img=2",
      lastMessage: "Let’s catch up soon!",
    },
  ];

  const groups: Group[] = [
    {
      id: "101",
      name: "Friends Group",
      avatar: "https://i.pravatar.cc/150?img=3",
    },
  ];

  const statusUpdates: StatusUpdate[] = [
    { id: "201", user: "John Doe", status: "Just chilling!", time: "2h ago" },
  ];

  const calls: Call[] = [
    {
      id: "301",
      name: "Jane Smith",
      time: "Yesterday, 5:30 PM",
      type: "video",
    },
  ];

  const handleSelectConversation = (conversation: Conversation) => {
    setSelectedConversation(conversation);
  };

  return (
    <div className="flex items-center justify-center h-screen bg-gradient-to-br from-[#1e1e2e] to-[#101018]">
      <div className="w-full h-full rounded-2xl text-white glassEffect overflow-hidden">
        <div className="flex">
          <Sidebar
            conversations={conversations}
            groups={groups}
            statusUpdates={statusUpdates}
            calls={calls}
            onSelectConversation={handleSelectConversation}
          />
          <div className="ml-[320px] w-full">
            {selectedConversation ? (
              <ChatWindow
                conversation={selectedConversation}
                messages={messages[selectedConversation.id] || []}
              />
            ) : (
              <div className="flex-1 flex items-center justify-center text-white text-lg">
                Select a conversation
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
